CREATE TABLE CPF_CACHE_INVALIDATION_EVENT (
    EVENT_ID BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    EVENT_KEY VARCHAR(180) NOT NULL,
    TENANT_ID VARCHAR(80) NOT NULL,
    NAMESPACE_NAME VARCHAR(80) NOT NULL,
    CACHE_KEY_VALUE VARCHAR(512) NULL,
    EVENT_VERSION BIGINT NOT NULL DEFAULT 0,
    REASON_TEXT VARCHAR(500) NOT NULL,
    REQUESTED_BY VARCHAR(180) NOT NULL,
    CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT UK_CPF_CACHE_INV_EVENT_KEY UNIQUE (EVENT_KEY),
    CONSTRAINT CK_CPF_CACHE_INV_VERSION CHECK (EVENT_VERSION >= 0)
);
CREATE INDEX IX_CPF_CACHE_INV_CREATED ON CPF_CACHE_INVALIDATION_EVENT (CREATED_AT);
CREATE INDEX IX_CPF_CACHE_INV_TARGET ON CPF_CACHE_INVALIDATION_EVENT (TENANT_ID, NAMESPACE_NAME, EVENT_ID);
CREATE TABLE CPF_CACHE_INVALIDATION_CHECKPOINT (
    CONSUMER_ID VARCHAR(180) PRIMARY KEY,
    LAST_EVENT_ID BIGINT NOT NULL DEFAULT 0,
    UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT CK_CPF_CACHE_INV_CHECKPOINT CHECK (LAST_EVENT_ID >= 0)
);
